#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Pin every download of the andarium-accessibility build as an archive row.

dependencies/build-andarium-accessibility.sh builds TalkBack and eSpeak NG
with Gradle offline, from the archives that `dependencies/prepare.sh
--archive-manifest dependencies/andarium-accessibility/archives.tsv` fetched
and verified: the two Gradle distributions and every Maven artifact the phone
release of either build resolves. This tool writes that list.

Everything here that reaches the network (the online Gradle builds and the
repository lookups) runs only from `dependencies/prepare.sh --product
andarium-accessibility --pin-archives PATH`, the one dependency workflow
allowed to access the network, which starts this tool as its own child. Run
directly, the tool refuses before it reads or fetches anything; `compare`
reads two lists and makes no network call.

    pin-archives.py pin --sources DIR --cache DIR --archives LIST --work DIR \\
        --java-home DIR --android-home DIR --output LIST
    pin-archives.py metadata --metadata XML [...] --distribution URL=SHA256 \\
        --output LIST
    pin-archives.py compare OLD NEW

`pin` builds the phone release of each application online, in a fresh Gradle
user home and with `--write-verification-metadata sha256`: Gradle records each
resolved artifact's SHA-256 but not where it came from, so the tool then
fetches the file from the repositories the builds name and keeps the first
whose bytes have that SHA-256, because one coordinate can name different bytes
in two repositories. `metadata` pins from metadata files that exist already.
A file Gradle names after its variant (a Kotlin multiplatform library's
metadata jar) lives where the component's .module file points, which is where
an offline build looks for it too. A Maven artifact's row is named
maven~GROUP~MODULE~VERSION~FILE after where it lives, which the builder lays
out as a Maven repository.
"""

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

import argparse
import concurrent.futures
import hashlib
import importlib.util
import json
import os
import re
import shutil
import subprocess
import sys
import urllib.error
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ElementTree
import zipfile
from pathlib import Path

# The repositories the builds may name: with the host that serves the Gradle
# distributions, the only hosts the pin run contacts.
REPOSITORIES = (
    "https://dl.google.com/dl/android/maven2",
    "https://repo.maven.apache.org/maven2",
    "https://plugins.gradle.org/m2",
)
HOSTS = tuple(urllib.parse.urlsplit(repository).hostname for repository in REPOSITORIES)
# The environment value prepare.sh --pin-archives sets for its child: its own
# process ID, which must be this process's parent.
PARENT_ENV = "UML_PREPARE_NETWORK_PARENT"
# What each application builds: the phone release only, never a test, a
# watch or a lint configuration. (source, project directory, task, Gradle)
BUILDS = (
    ("talkback", ".", "assemblePhoneRelease", "gradle-8.14.3"),
    ("espeak-ng", "android", "assembleRelease", "gradle-9.6.1"),
)
NAMESPACE = "{https://schema.gradle.org/dependency-verification}"
NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9._+%~-]*")
HEADER = """# SPDX-License-Identifier: GPL-2.0-or-later
# Every download of dependencies/build-andarium-accessibility.sh: the Gradle
# distributions and each Maven artifact the phone release builds of TalkBack
# and eSpeak NG resolve. Generated by dependencies/andarium-accessibility/
# pin-archives.py through prepare.sh --pin-archives; regenerate it rather than
# editing it. dependencies/prepare.sh --archive-manifest fetches and verifies
# the rows, and the builder runs Gradle offline from them.
"""
# Gradle's init script of the online run: every repository a build or its
# settings names must be a Maven repository on one of the hosts above.
INIT_SCRIPT = """def allowed = [%(hosts)s] as Set
def check = { repositories ->
    repositories.all { repository ->
        if (repository.name.startsWith('__plugin_repository__')) {
            return
        }
        if (!(repository instanceof MavenArtifactRepository)) {
            throw new GradleException("online pin run: ${repository.name} is not a Maven repository")
        }
        def location = repository.url
        if (location.scheme != 'https' || !allowed.contains(location.host)) {
            throw new GradleException("online pin run: ${repository.name} names ${location}, which is not an allowed repository")
        }
    }
}
beforeSettings { settings ->
    check(settings.pluginManagement.repositories)
    check(settings.dependencyResolutionManagement.repositories)
}
allprojects { project ->
    check(project.buildscript.repositories)
    check(project.repositories)
}
"""


def fail(message: str) -> None:
    raise SystemExit(f"pin-archives.py: {message}")


def require_prepare() -> None:
    """Refuses unless prepare.sh --pin-archives started this process."""
    parent = os.environ.get(PARENT_ENV, "")
    if not parent.isdigit() or int(parent) != os.getppid():
        fail("this reaches the network, which only dependencies/prepare.sh may do: run "
             "`dependencies/prepare.sh --product andarium-accessibility --pin-archives PATH`")


# ----------------------------------------------------------------- files --


def artifacts(metadata: Path) -> set[tuple[str, str, str, str, str]]:
    """(group, module, version, file, sha256) of each artifact the file lists."""
    found = set()
    root = ElementTree.parse(metadata).getroot()
    for component in root.iter(f"{NAMESPACE}component"):
        group, module, version = (component.get(key) for key in ("group", "name", "version"))
        for artifact in component.findall(f"{NAMESPACE}artifact"):
            digest = artifact.find(f"{NAMESPACE}sha256")
            if digest is None:
                fail(f"{metadata}: {group}:{module}:{version} {artifact.get('name')} has no sha256")
            found.add((group, module, version, artifact.get("name"), digest.get("value")))
    if not found:
        fail(f"{metadata} lists no artifact")
    return found


def archive_name(url: str) -> str:
    """maven~GROUP~MODULE~VERSION~FILE for where the file lives."""
    for repository in REPOSITORIES:
        if url.startswith(repository + "/"):
            parts = url[len(repository) + 1:].split("/")
            if len(parts) >= 4:
                return "maven~" + "~".join([".".join(parts[:-3]), *parts[-3:]])
    fail(f"not a repository path: {url}")
    return ""


def read_list(path: Path) -> dict[str, tuple[str, str]]:
    """name -> (url, sha256) of an archive list."""
    rows = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line or line.startswith("#") or line == "name\turl\tsha256":
            continue
        fields = line.split("\t")
        if len(fields) != 3:
            fail(f"{path}: a row is name, url and sha256")
        rows[fields[0]] = (fields[1], fields[2])
    return rows


def distributions(archives: Path) -> list[tuple[str, str, str]]:
    """The Gradle distribution rows of a list: (name, url, sha256)."""
    return [(name, url, digest) for name, (url, digest) in read_list(archives).items() if name.endswith("-bin.zip")]


def render(rows: list[tuple[str, str, str]]) -> str:
    return "".join([HEADER, "name\turl\tsha256\n"] + [f"{name}\t{url}\t{digest}\n" for name, url, digest in rows])


def compare(old: Path, new: Path) -> tuple[list[str], int]:
    """Lines saying how `new` differs from `old`, and how many rows both
    lists have with the same digest. A row `old` has with another digest is
    the change that matters: the same name must name the same bytes."""
    before, after = read_list(old), read_list(new)
    lines = []
    for name in sorted(set(before) | set(after)):
        if name not in after:
            lines.append(f"removed\t{name}\t{before[name][1]}")
        elif name not in before:
            lines.append(f"new\t{name}\t{after[name][1]}\t{after[name][0]}")
        elif before[name][1] != after[name][1]:
            lines.append(f"DIFFERS\t{name}\t{before[name][1]}\t{after[name][1]}")
        elif before[name][0] != after[name][0]:
            lines.append(f"url\t{name}\t{before[name][0]}\t{after[name][0]}")
    same = sum(1 for name in before if name in after and before[name][1] == after[name][1])
    return lines, same


# --------------------------------------------------------------- network --


def serves(url: str, digest: str) -> bool:
    """Whether `url` serves bytes whose SHA-256 is `digest`."""
    require_prepare()
    request = urllib.request.Request(url, headers={"User-Agent": "dependency-pin-archives"})
    try:
        with urllib.request.urlopen(request, timeout=120) as response:
            sha256 = hashlib.sha256()
            for block in iter(lambda: response.read(1 << 20), b""):
                sha256.update(block)
            return sha256.hexdigest() == digest
    except urllib.error.HTTPError as error:
        if error.code in (403, 404):
            return False
        raise


def module_file(url: str) -> dict | None:
    require_prepare()
    request = urllib.request.Request(url, headers={"User-Agent": "dependency-pin-archives"})
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        if error.code in (403, 404):
            return None
        raise


def locate(entry: tuple[str, str, str, str, str]) -> str:
    """The URL of the file, directly under its component or where the
    component's Gradle module metadata points."""
    group, module, version, file, digest = entry
    directory = f"{group.replace('.', '/')}/{module}/{version}"
    for repository in REPOSITORIES:
        if serves(f"{repository}/{directory}/{file}", digest):
            return f"{repository}/{directory}/{file}"
    for repository in REPOSITORIES:
        metadata_url = f"{repository}/{directory}/{module}-{version}.module"
        metadata = module_file(metadata_url)
        if metadata is None:
            continue
        for variant in metadata.get("variants", []):
            for variant_file in variant.get("files", []):
                if variant_file.get("name") == file:
                    url = urllib.parse.urljoin(metadata_url, variant_file["url"])
                    if serves(url, digest):
                        return url
    fail(f"no repository serves {directory}/{file} with its SHA-256")
    return ""


def pin(entries: set, rows: list[tuple[str, str, str]]) -> list[tuple[str, str, str]]:
    """`rows` (the distributions) and one row per artifact, found in the repositories."""
    ordered = sorted(entries)
    with concurrent.futures.ThreadPoolExecutor(max_workers=16) as pool:
        urls = list(pool.map(locate, ordered))
    pinned: dict[str, tuple[str, str]] = {}
    for (_, _, _, _, digest), url in zip(ordered, urls):
        name = archive_name(url)
        if not NAME.fullmatch(name):
            fail(f"an artifact's name cannot be an archive name: {name}")
        if name in pinned and pinned[name] != (url, digest):
            fail(f"two artifacts live at {url} with different contents")
        pinned[name] = (url, digest)
    rows = rows + [(name, url, digest) for name, (url, digest) in sorted(pinned.items())]
    names = [row[0] for row in rows]
    if len(names) != len(set(names)):
        fail("two archives share a name")
    return rows


# ---------------------------------------------------------------- gradle --


def identity_module(root: Path):
    path = root / "dependencies/andarium-accessibility/identity.py"
    specification = importlib.util.spec_from_file_location("accessibility_identity", path)
    module = importlib.util.module_from_spec(specification)
    sys.modules[specification.name] = module
    specification.loader.exec_module(module)
    return module


def gradle_command(distribution: Path, project: Path, home: Path, init: Path, task: str, extra: list[str]) -> list[str]:
    """One online build of a phone release that writes the verification metadata."""
    return [
        str(distribution / "bin/gradle"), "--no-daemon", "--console=plain",
        "--gradle-user-home", str(home), "--init-script", str(init),
        "--project-dir", str(project),
        "--write-verification-metadata", "sha256",
        "-Pandroid.builder.sdkDownload=false", *extra, task,
    ]


def online_metadata(root: Path, sources: Path, cache: Path, archives: Path, work: Path,
                    java_home: Path, android_home: Path) -> tuple[list[Path], list[tuple[str, str, str]]]:
    """Builds each application's phone release online and returns the
    verification metadata files and the Gradle distribution rows."""
    require_prepare()
    identity = identity_module(root)
    _, problems = identity.observe_toolchain(java_home, android_home, identity.tracked_toolchain(root))
    if problems:
        fail("the JDK and SDK are not the pinned toolchain:\n  " + "\n  ".join(problems))
    rows = distributions(archives)
    by_name = {name: digest for name, _, digest in rows}
    shutil.rmtree(work, ignore_errors=True)
    work.mkdir(parents=True)
    init = work / "online.gradle"
    init.write_text(INIT_SCRIPT % {"hosts": ", ".join(f"'{host}'" for host in HOSTS)}, encoding="utf-8")
    environment = {**os.environ, "JAVA_HOME": str(java_home), "ANDROID_HOME": str(android_home)}
    metadata = []
    for name, subdirectory, task, gradle in BUILDS:
        archive = f"{gradle}-bin.zip"
        if archive not in by_name:
            fail(f"{archives} has no row for {archive}")
        cached = cache / "archives" / f"{by_name[archive]}-{archive}"
        if not cached.is_file():
            fail(f"{archive} is not in the dependency cache; prepare.sh fetches it first")
        with zipfile.ZipFile(cached) as distribution:
            distribution.extractall(work / name)
        for script in (work / name / gradle / "bin").iterdir():
            script.chmod(0o755)
        export = work / name / "source"
        export.mkdir()
        exporter = subprocess.Popen(["git", "-C", str(sources / name), "archive", "HEAD"], stdout=subprocess.PIPE)
        unpacked = subprocess.run(["tar", "-x", "-C", str(export)], stdin=exporter.stdout, check=False)
        exporter.stdout.close()
        if exporter.wait() != 0 or unpacked.returncode != 0:
            fail(f"cannot export {name}")
        project = export / subdirectory
        (project / "local.properties").write_text(f"sdk.dir={android_home}\n", encoding="utf-8")
        written = project / "gradle/verification-metadata.xml"
        written.unlink(missing_ok=True)
        extra = [f"-PsonicSourceDir={sources / 'sonic'}"] if name == "espeak-ng" else []
        command = gradle_command(work / name / gradle, project, work / name / "gradle-home", init, task, extra)
        if subprocess.run(command, env=environment, check=False).returncode != 0:
            fail(f"the online {task} of {name} failed")
        if not written.is_file():
            fail(f"the online {task} of {name} wrote no verification metadata")
        metadata.append(written)
    return metadata, rows


# ------------------------------------------------------------------- cli --


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    commands = parser.add_subparsers(dest="command", required=True)
    pin_command = commands.add_parser("pin")
    pin_command.add_argument("--sources", type=Path, required=True)
    pin_command.add_argument("--cache", type=Path, required=True)
    pin_command.add_argument("--archives", type=Path, required=True, help="the list that names the Gradle distributions")
    pin_command.add_argument("--output", type=Path, required=True)
    pin_command.add_argument("--work", type=Path, required=True)
    pin_command.add_argument("--java-home", type=Path, required=True)
    pin_command.add_argument("--android-home", type=Path, required=True)
    pin_command.add_argument("--repo-root", type=Path, default=Path(__file__).resolve().parents[2])
    metadata_command = commands.add_parser("metadata")
    metadata_command.add_argument("--metadata", type=Path, action="append", required=True,
                                  help="a gradle/verification-metadata.xml written with sha256")
    metadata_command.add_argument("--distribution", action="append", default=[],
                                  help="URL=SHA256 of a Gradle distribution")
    metadata_command.add_argument("--output", type=Path, required=True)
    compare_command = commands.add_parser("compare")
    compare_command.add_argument("old", type=Path)
    compare_command.add_argument("new", type=Path)
    args = parser.parse_args()

    if args.command == "compare":
        lines, same = compare(args.old, args.new)
        print("\n".join(lines))
        print(f"{same} rows keep their digest", file=sys.stderr)
        return 1 if any(line.startswith("DIFFERS") for line in lines) else 0

    require_prepare()
    if args.command == "pin":
        files, rows = online_metadata(
            args.repo_root.resolve(), args.sources, args.cache, args.archives, args.work,
            args.java_home, args.android_home)
    else:
        files, rows = args.metadata, []
        for distribution in args.distribution:
            url, _, digest = distribution.partition("=")
            if not url.startswith("https://") or not re.fullmatch(r"[0-9a-f]{64}", digest):
                fail(f"--distribution needs HTTPS_URL=SHA256: {distribution}")
            rows.append((url.rsplit("/", 1)[1], url, digest))
    entries = set()
    for path in files:
        entries |= artifacts(path)
    pinned = pin(entries, rows)
    args.output.write_text(render(pinned), encoding="utf-8")
    print(f"pin-archives.py: {len(pinned)} rows in {args.output}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
